    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: Which cognitive bias involves relying too heavily on the first piece of information offered (the "anchor") when making decisions?', '["Availability Bias", "Anchoring Bias", "Confirmation Bias", "Premature Closure"]', 1, 'Anchoring bias occurs when a clinician fixes on an initial finding and fails to adjust their diagnosis in light of subsequent data.'),
    (v_topic_id, '2: A physician diagnoses a patient with "Flu" because they have seen 10 cases of flu today, ignoring signs of meningitis. This is an example of:', '["Availability Bias", "Representativeness Bias", "Blind Spot Bias", "Omission Bias"]', 0, 'Availability bias is the tendency to judge the probability of an event based on how easily examples come to mind.'),
    (v_topic_id, '3: "Premature Closure" in clinical reasoning is best defined as:', '["Ending the patient interview too early", "Accepting a diagnosis before it has been fully verified", "Failing to order labs", "Discharging a patient early"]', 1, 'It is the most common cause of diagnostic error, where the clinician stops searching for alternatives once a plausible diagnosis is found.'),
    (v_topic_id, '4: "Confirmation Bias" involves:', '["Seeking information that supports a pre-conceived diagnosis and ignoring data that contradicts it", "Asking the patient for confirmation", "Repeating a lab test", "Consulting a specialist"]', 0, 'Clinicians may selectively look for evidence that proves their initial "hunch."'),
    (v_topic_id, '5: Which heuristic involves judging the probability of a disease based on how closely the patient''s presentation matches a "classic" textbook case?', '["Availability Heuristic", "Representativeness Heuristic", "Anchoring Heuristic", "Framing Effect"]', 1, 'While often useful, it can lead to missing atypical presentations of common diseases.'),
    (v_topic_id, '6: "Blind Spot Bias" refers to:', '["A visual field defect", "The tendency to see biases in others but not in oneself", "Missing a finding on an X-ray", "Ignoring a patient''s family history"]', 1, 'It is the meta-bias where we believe we are more objective than our colleagues.'),
    (v_topic_id, '7: In "Bayesian Reasoning," the "Pre-test Probability" is updated by the result of a test to produce a:', '["Pre-test Odds", "Post-test Probability", "Likelihood Ratio", "P-value"]', 1, 'The post-test probability depends on both the test result and the clinical suspicion before the test.'),
    (v_topic_id, '8: A "Likelihood Ratio" (LR) of _____ indicates that the test result does not change the probability of disease at all.', '["0", "1.0", "10", "Infinity"]', 1, 'An LR of 1.0 means the test is uninformative.'),
    (v_topic_id, '9: A "Positive Likelihood Ratio" (LR+) > _____ is generally considered to provide a large and often conclusive increase in the probability of disease.', '["2", "5", "10", "1"]', 2, 'LR+ = Sensitivity / (1 - Specificity). Values > 10 are very powerful.'),
    (v_topic_id, '10: A "Negative Likelihood Ratio" (LR-) < _____ is generally considered to provide a large and often conclusive decrease in the probability of disease.', '["0.1", "0.5", "1.0", "2.0"]', 0, 'LR- = (1 - Sensitivity) / Specificity. Values < 0.1 are excellent for "ruling out."'),
    (v_topic_id, '11: "Sensitivity" is the probability that a test is positive given that:', '["The patient has the disease", "The patient does NOT have the disease", "The patient is symptomatic", "The test is repeated"]', 0, 'SNOpin: A highly SeNsitive test, when Negative, rules the disease out.'),
    (v_topic_id, '12: "Specificity" is the probability that a test is negative given that:', '["The patient has the disease", "The patient does NOT have the disease", "The patient is healthy", "The patient is old"]', 1, 'SPPIn: A highly SPecific test, when Positive, rules the disease in.'),
    (v_topic_id, '13: "Positive Predictive Value" (PPV) is the probability that a patient has the disease given:', '["A positive test result", "A negative test result", "Symptoms", "Risk factors"]', 0, 'Unlike Sensitivity/Specificity, PPV depends heavily on the prevalence of the disease in the population.'),
    (v_topic_id, '14: If the "Prevalence" of a disease increases in a population, the PPV of a test will _____ and the NPV will _____:', '["Increase; Decrease", "Decrease; Increase", "Stay the same; Stay the same", "Increase; Increase"]', 0, 'As a disease becomes more common, a positive result is more likely to be a true positive.'),
    (v_topic_id, '15: "Sutton''s Law" in clinical reasoning suggests:', '["Always order the cheapest test first", "Go where the money is (target the most likely diagnosis first)", "Look for rare diseases", "Never trust the history"]', 1, 'Named after bank robber Willie Sutton, it encourages focusing on the highest probability etiologies.'),
    (v_topic_id, '16: "Occam''s Razor" (the principle of parsimony) suggests that:', '["Rare diseases are common", "The simplest explanation that accounts for all findings is usually correct", "A patient can have multiple unrelated diseases", "Always use a scalpel"]', 1, 'Aim for a single unifying diagnosis when possible.'),
    (v_topic_id, '17: "Hickam''s Dictum" is the counter-argument to Occam''s Razor, stating:', '["Patients can have as many diseases as they damn well please", "One disease is enough", "Never assume anything", "History is everything"]', 0, 'Common in elderly or complex patients who often have multiple co-existing pathologies.'),
    (v_topic_id, '18: "System 1" thinking is characterized as:', '["Slow, analytical, and effortful", "Fast, intuitive, and subconscious", "Error-free", "Scientific"]', 1, 'Most "pattern recognition" in medicine is System 1.'),
    (v_topic_id, '19: "System 2" thinking is characterized as:', '["Fast and automatic", "Slow, deliberate, and logical", "Emotional", "Lazy"]', 1, 'We use System 2 when a case is complex, unfamiliar, or when System 1 fails.'),
    (v_topic_id, '20: The "Fagan Nomogram" is a graphical tool used to calculate:', '["Drug doses", "Post-test probability using pre-test probability and Likelihood Ratios", "Heart rate", "Body surface area"]', 1, 'It allows clinicians to quickly apply LR to their clinical suspicion.'),
    (v_topic_id, '21: "Base Rate Neglect" is a cognitive bias where a clinician:', '["Ignores the underlying prevalence of a disease", "Forgets the patient''s name", "Miscalculates a dose", "Ignores the heart rate"]', 0, 'A clinician might focus on a "classic" but rare finding and ignore that the disease itself is extremely rare in that population.'),
    (v_topic_id, '22: "Zebra Retreat" occurs when a clinician:', '["Finds a rare disease", "Shies away from a rare but correct diagnosis because they are afraid of being perceived as over-diagnosing", "Treats every patient the same", "Stops working"]', 1, '"When you hear hoofbeats, think horses, not zebras," but sometimes it really is a zebra.'),
    (v_topic_id, '23: "Diagnostic Momentum" refers to:', '["The speed of a diagnosis", "The tendency for a diagnosis to become established and unquestioned as it is passed from one clinician to another", "Aggressive treatment", "Rapid lab results"]', 1, 'If the ER notes "Pneumonia," the admitting team may stop considering other causes of chest pain.'),
    (v_topic_id, '24: A "Negative" test with a LOW Negative Likelihood Ratio (LR- < 0.1) is best for:', '["Ruling IN a disease", "Ruling OUT a disease", "Confirming a diagnosis", "Monitoring"]', 1, 'It significantly lowers the probability of the disease.'),
    (v_topic_id, '25: "Internal Validity" of a clinical study refers to:', '["How well the results apply to your specific patient", "The extent to which the study results are true for the people in the study (minimized bias)", "The size of the study", "The funding source"]', 1, 'A study must be internally valid before its external validity (generalizability) can be considered.'),
    (v_topic_id, '26: "External Validity" (Generalizability) refers to:', '["Whether the study was blinded", "Whether the study results can be applied to other populations/patients", "The statistical power", "The p-value"]', 1, 'Can I apply this study of middle-aged men to my 80-year-old female patient?'),
    (v_topic_id, '27: "Number Needed to Treat" (NNT) is calculated as:', '["1 / Absolute Risk Reduction (ARR)", "1 / Relative Risk", "Risk in Control - Risk in Treatment", "Total patients / Successes"]', 0, 'The lower the NNT, the more effective the treatment.'),
    (v_topic_id, '28: "Incidence" is defined as:', '["Total number of cases at a point in time", "Number of NEW cases over a specific period", "Deaths from a disease", "Rate of recovery"]', 1, 'Incidence = NEW cases / Population at risk.'),
    (v_topic_id, '29: "Prevalence" is defined as:', '["New cases only", "Total number of cases in a population at a specific point in time", "Severity of disease", "Likelihood of transmission"]', 1, 'Prevalence \u2248 Incidence x Duration of disease.'),
    (v_topic_id, '30: "Lead-Time Bias" occurs in screening when:', '["The screen finds a more aggressive disease", "Early detection is confused with increased survival, even if the timing of death is unchanged", "The test takes too long to result", "The patient is late"]', 1, 'The patient simply lives longer *knowing* they have the disease.'),
    (v_topic_id, '31: "Length-Time Bias" occurs because screening is more likely to detect:', '["Fast-growing, aggressive tumors", "Slow-growing, less aggressive tumors with a longer asymptomatic period", "Infections", "Trauma"]', 1, 'This makes it seem like screening saves lives by finding "better" cases.'),
    (v_topic_id, '32: A "Case-Control" study is best for studying:', '["Rare diseases", "New treatments", "Incidence", "Prevention"]', 0, 'You start with the "cases" (diseased) and look back at "controls" (not diseased) for exposures.'),
    (v_topic_id, '33: A "Cohort Study" is best for studying:', '["Rare diseases", "Risk factors and incidence (starting with exposure and following over time)", "Drug efficacy", "Prevalence"]', 1, 'It can be prospective or retrospective.'),
    (v_topic_id, '34: "Randomized Controlled Trial" (RCT) is the gold standard for:', '["Prognosis", "Therapy/Intervention", "Prevalence", "Diagnosis"]', 1, 'Randomization minimizes confounding.'),
    (v_topic_id, '35: "Meta-analysis" involves:', '["A single large trial", "Statistical combination of results from multiple independent studies", "Expert opinion", "A case series"]', 1, 'It provides a more precise estimate of effect size.'),
    (v_topic_id, '36: "Sensitivity Analysis" in clinical reasoning refers to:', '["The test sensitivity", "Checking how much the post-test probability changes if the pre-test probability is slightly different", "Being nice to patients", "Skin testing"]', 1, 'It helps determine if the diagnostic decision is "robust."'),
    (v_topic_id, '37: "Ecological Fallacy" occurs when:', '["You forget to recycle", "Inferences about individuals are made based on aggregate data for a group", "The study is too small", "The p-value is 0.05"]', 1, 'Just because a country has high fat intake and high heart disease doesn''t mean every individual who eats fat gets heart disease.'),
    (v_topic_id, '38: "Confounding" is a situation where the relationship between an exposure and an outcome is:', '["True", "Distorted by a third variable associated with both the exposure and the outcome", "Clear", "Insignificant"]', 1, 'Example: Alcohol use is associated with lung cancer, but smoking is the confounder.'),
    (v_topic_id, '39: "Hawthorne Effect" refers to:', '["Better results in the winter", "Participants changing their behavior because they know they are being studied", "A type of plant", "Error in lab"]', 1, 'This can lead to improved outcomes in both arms of a study.'),
    (v_topic_id, '40: "Publication Bias" occurs when:', '["Only large studies are published", "Positive results are more likely to be published than negative or null results", "Authors are famous", "The journal is expensive"]', 1, 'This can distort meta-analyses to make interventions look more effective than they are.'),
    (v_topic_id, '41: A "Pilot Study" is primarily used to:', '["Prove a hypothesis", "Test the feasibility and refine the methodology of a larger study", "Publish quickly", "Train medical students"]', 1, 'It is not powered to show definitive results.'),
    (v_topic_id, '42: "Intention-to-Treat" (ITT) analysis includes:', '["Only those who completed the study", "All participants as originally randomized, regardless of whether they completed the treatment", "Only the successes", "Only the healthy ones"]', 1, 'This preserves the benefits of randomization and reflects real-world effectiveness.'),
    (v_topic_id, '43: "Double-Blinding" means:', '["Neither the patient nor the researcher knows who is in which group", "The doctor wears glasses", "Two tests are done", "The study is done twice"]', 0, 'It minimizes observer and participant bias.'),
    (v_topic_id, '44: "P-value" of 0.05 means:', '["The result is definitely true", "There is a 5% chance the observed result occurred by random chance alone (assuming the null hypothesis is true)", "The effect is large", "The study was perfect"]', 1, 'It does not measure the clinical significance of the effect.'),
    (v_topic_id, '45: "Type I Error" (Alpha) is:', '["False negative", "False positive (rejecting the null hypothesis when it is actually true)", "Too many patients", "Wrong math"]', 1, 'Concluding there is a difference when none exists.'),
    (v_topic_id, '46: "Type II Error" (Beta) is:', '["False positive", "False negative (failing to reject the null hypothesis when a true difference exists)", "Perfect study", "Big p-value"]', 1, 'Concluding there is no difference when one actually exists.'),
    (v_topic_id, '47: "Power" of a study is calculated as:', '["1 - Alpha", "1 - Beta", "Sensitivity + Specificity", "Mean / SD"]', 1, 'It is the probability of finding a difference if one truly exists.'),
    (v_topic_id, '48: "Standard Deviation" (SD) measures the:', '["Mean", "Dispersion of data around the mean", "The error", "Number of patients"]', 1, 'It describes the variability within the sample.'),
    (v_topic_id, '49: "Standard Error of the Mean" (SEM) measures the:', '["Sample size", "Precision of the sample mean as an estimate of the population mean", "The max value", "The min value"]', 1, 'SEM = SD / square root of n.'),
    (v_topic_id, '50: "Confidence Interval" (95% CI) that includes the value _____ for an Odds Ratio or Relative Risk indicates the result is NOT statistically significant.', '["0", "1.0", "10", "100"]', 1, 'If the CI crosses 1.0, the risk could be the same in both groups.'),
    (v_topic_id, '51: "Framing Effect" in clinical reasoning refers to:', '["The size of the hospital", "How information is presented (e.g., 90% survival vs 10% mortality) affecting decision making", "Putting a picture on the wall", "Laboratory borders"]', 1, 'People are often more risk-averse when options are framed as losses.'),
    (v_topic_id, '52: "Sunk Cost Fallacy" in medicine might involve:', '["Buying cheap equipment", "Continuing a failing treatment or diagnostic path because of the time and effort already invested", "Charging too much", "Going home early"]', 1, 'The "we''ve already done X, we might as well keep going" mentality.'),
    (v_topic_id, '53: "Ascertainment Bias" occurs when:', '["The patient is late", "The samples collected are not representative of the target population", "The lab is closed", "The doctor is tired"]', 1, 'Common in hospital-based studies (Berkson''s bias).'),
    (v_topic_id, '54: "Recall Bias" is a major problem in which study type?', '["Cohort", "Case-Control", "RCT", "Meta-analysis"]', 1, 'People with a disease are more likely to remember potential exposures than healthy controls.'),
    (v_topic_id, '55: "Relative Risk" (RR) is calculated by comparing:', '["Risk in the exposed group to risk in the unexposed group", "Odds", "Means", "Medians"]', 0, 'RR = [a/(a+b)] / [c/(c+d)].'),
    (v_topic_id, '56: "Odds Ratio" (OR) is used in Case-Control studies as an estimate of:', '["Incidence", "Relative Risk", "Prevalence", "Death rate"]', 1, 'OR \u2248 RR if the disease is rare.'),
    (v_topic_id, '57: "Absolute Risk Reduction" (ARR) is:', '["Risk_Control - Risk_Treatment", "1 - RR", "Incidence / Prevalence", "Total deaths"]', 0, 'It tells you the actual percentage drop in risk.'),
    (v_topic_id, '58: "Relative Risk Reduction" (RRR) is:', '["1 - RR", "ARR", "1 / ARR", "Mean difference"]', 0, 'It often sounds more impressive than ARR.'),
    (v_topic_id, '59: "Number Needed to Harm" (NNH) is:', '["Total patients", "1 / Absolute Risk Increase (ARI)", "Death rate", "Error rate"]', 1, 'The number of patients who must be treated for one to experience an adverse event.'),
    (v_topic_id, '60: "Clinical Significance" differs from "Statistical Significance" because it:', '["Is always true", "Refers to whether the observed effect is large enough to matter to the patient", "Is smaller", "Uses p-values"]', 1, 'A p-value of 0.001 can accompany a tiny, clinically irrelevant change.'),
    (v_topic_id, '61: "Likelihood Ratio" (LR) is preferred over Sensitivity/Specificity because:', '["It is easier to say", "It does not change with disease prevalence and can be used to calculate post-test probability directly", "It is always 1", "It is only for doctors"]', 1, 'It combines sensitivity and specificity into a single, clinically useful number.'),
    (v_topic_id, '62: "Deductive Reasoning" moves from:', '["Specific to general", "General principles to specific conclusions", "Fast to slow", "Wrong to right"]', 1, 'Example: All patients with X have Y. This patient has X. Therefore, this patient has Y.'),
    (v_topic_id, '63: "Inductive Reasoning" moves from:', '["General to specific", "Specific observations to general probabilities", "Math to logic", "Normal to abnormal"]', 1, 'Most clinical diagnosis is inductive.'),
    (v_topic_id, '64: "Abductive Reasoning" (Inference to the best explanation) is:', '["Stealing a diagnosis", "Formulating the most likely hypothesis based on incomplete information", "Pure logic", "Random guessing"]', 1, 'This is the core of "Diagnostic Reasoning."'),
    (v_topic_id, '65: A "Pathognomonic" finding is one that is:', '["Common", "Absolutely diagnostic of a specific disease (100% Specificity)", "Very rare", "Painful"]', 1, 'Example: Koplik spots in measles.'),
    (v_topic_id, '66: A "Sine Qua Non" finding is one that:', '["Is rare", "Must be present for the diagnosis to be made (100% Sensitivity)", "Is useless", "Is expensive"]', 1, 'If it''s absent, the disease is ruled out.'),
    (v_topic_id, '67: "Heuristics" are best described as:', '["Mathematical formulas", "Mental shortcuts or \"rules of thumb\" used to solve complex problems quickly", "Errors", "Textbooks"]', 1, 'They are essential for efficient clinical practice but prone to predictable biases.'),
    (v_topic_id, '68: "Search Satisficing" is the tendency to:', '["Stop searching once any abnormality is found, even if it doesn''t explain everything", "Order every test", "Keep looking forever", "Be happy"]', 0, 'Example: Finding a fractured rib on CXR and missing the pneumothorax.'),
    (v_topic_id, '69: "Affective Error" occurs when a clinician''s reasoning is influenced by:', '["The patient''s age", "Emotions or personal feelings toward a patient (positive or negative)", "The time of day", "The weather"]', 1, 'Example: Avoiding a thorough exam on a "difficult" patient.'),
    (v_topic_id, '70: "Unpacking Principle" refers to:', '["Opening a medical bag", "The tendency for more specific descriptions of a problem to be judged as more likely than general ones", "Solving a case", "Taking off a bandage"]', 1, 'A clinician might think "Strep throat" is more likely than "Sore throat" even though they are subsets.'),
    (v_topic_id, '71: "Triage Cueing" occurs when:', '["The patient is seen quickly", "Initial triage labels (e.g., \"psych patient\" or \"drug seeker\") bias all subsequent evaluations", "The nurse is busy", "The ER is full"]', 1, 'It is a form of anchoring and framing.'),
    (v_topic_id, '72: "Visceral Bias" is:', '["Pain in the gut", "Negative or positive feelings toward patients that affect the quality of care (e.g., homelessness, obesity)", "A type of scan", "An error in the lab"]', 1, 'Similar to affective error.'),
    (v_topic_id, '73: "Cognitive Debiasing" strategies include:', '["Using diagnostic checklists", "Taking a \"diagnostic pause\" to consider alternatives", "Metacognition (thinking about how you think)", "All of the above"]', 3, 'These techniques help mitigate the impact of System 1 errors.'),
    (v_topic_id, '74: "Evidence-Based Medicine" (EBM) is the integration of best research evidence with:', '["Clinical expertise and patient values/preferences", "Textbook rules only", "The cheapest option", "Insurance policies"]', 0, 'It is a "triad" of evidence, expertise, and values.'),
    (v_topic_id, '75: "Critical Appraisal" of a study involves evaluating its:', '["Validity, Importance/Impact, and Applicability", "Length", "Author names", "Price"]', 0, 'Is the study true? Is the effect big? Can I use it for my patient?'),
    (v_topic_id, '76: "Forest Plot" is a graphical representation used in:', '["Biology", "Meta-analyses (showing results of individual studies and the pooled estimate)", "Surgery", "X-rays"]', 1, 'It looks like a series of lines with a diamond at the bottom.'),
    (v_topic_id, '77: "Funnel Plot" is used to detect:', '["Heart failure", "Publication bias", "Fluid flow", "Airway obstruction"]', 1, 'An asymmetrical funnel suggests that small negative studies are missing.'),
    (v_topic_id, '78: "Number Needed to Screen" (NNS) is:', '["Total population", "The number of people who must be screened to prevent one adverse event or death", "Cost per screen", "Number of tests"]', 1, 'Used to evaluate the public health impact of screening programs.'),
    (v_topic_id, '79: "Survival Analysis" often uses the "Kaplan-Meier Curve" which plots:', '["Weight over time", "The proportion of participants surviving (or event-free) over time", "Drug levels", "Heart rate"]', 1, 'It accounts for "censored" data (participants lost to follow-up).'),
    (v_topic_id, '80: "Censoring" in survival analysis occurs when:', '["Information is hidden", "The outcome of interest has not occurred for a participant by the end of the study", "The study is cancelled", "The results are bad"]', 1, 'The participant may have dropped out or the study simply ended.'),
    (v_topic_id, '81: "Hazard Ratio" (HR) is similar to Relative Risk but is used for:', '["Snapshot data", "Time-to-event data", "Means", "Medians"]', 1, 'It represents the instantaneous risk of an event.'),
    (v_topic_id, '82: "Non-inferiority Trial" is designed to show that:', '["The new treatment is better than the old", "The new treatment is NOT significantly WORSE than the existing standard", "The treatment is useless", "The study failed"]', 1, 'Often used when the new treatment is cheaper, safer, or easier to take.'),
    (v_topic_id, '83: "Composite Endpoint" in a trial:', '["Uses only one outcome", "Combines several related outcomes (e.g., MI + Stroke + Death) into one", "Is more expensive", "Is less powerful"]', 1, 'It increases the number of events, improving statistical power but can be misleading if components differ in importance.'),
    (v_topic_id, '84: "Surrogate Endpoint" is a measure that is:', '["The final goal (e.g., survival)", "A laboratory or physical sign intended to substitute for a clinical endpoint (e.g., BP instead of stroke)", "A fake result", "The doctor''s opinion"]', 1, 'Surrogates don''t always correlate perfectly with the clinical outcome of interest.'),
    (v_topic_id, '85: "Standardized Mean Difference" (Cohen''s d) is a measure of:', '["P-value", "Effect size", "Sample size", "Range"]', 1, 'It describes the magnitude of the difference between groups in terms of standard deviations.'),
    (v_topic_id, '86: "Inter-rater Reliability" (Kappa) measures the:', '["The accuracy of a test", "Agreement between two different observers beyond what is expected by chance", "The speed of a test", "The cost"]', 1, 'A Kappa of 0.8 is excellent agreement; 0 is chance agreement.'),
    (v_topic_id, '87: "Diagnostic Strategy" - "Serial Testing" (performing tests one after another) is used to:', '["Increase Sensitivity", "Increase Specificity (minimize false positives)", "Save time", "Use more machines"]', 1, 'A patient must be positive on ALL tests to be considered diseased.'),
    (v_topic_id, '88: "Diagnostic Strategy" - "Parallel Testing" (performing multiple tests at once) is used to:', '["Increase Specificity", "Increase Sensitivity (minimize false negatives)", "Decrease costs", "Use fewer tubes"]', 1, 'A patient is considered diseased if ANY test is positive.'),
    (v_topic_id, '89: "Validity" of a test means:', '["It gives the same result every time", "It measures what it is intended to measure (Accuracy)", "It is fast", "It is cheap"]', 1, 'A valid test is one that hits the "bullseye."'),
    (v_topic_id, '90: "Reliability" (Precision) of a test means:', '["It is accurate", "It gives consistent results when repeated", "It is expensive", "It is new"]', 1, 'A reliable test clusters its results closely together, even if they aren''t on the bullseye.'),
    (v_topic_id, '91: "ROC Curve" (Receiver Operating Characteristic) plots:', '["Sensitivity vs (1 - Specificity)", "Mean vs SD", "Risk vs Time", "Cost vs Benefit"]', 0, 'The "Area Under the Curve" (AUC) measures the overall accuracy of the test.'),
    (v_topic_id, '92: An "AUC" (Area Under the Curve) of _____ represents a perfectly accurate test.', '["0.5", "1.0", "0", "100"]', 1, 'An AUC of 0.5 represents a test no better than a coin flip.'),
    (v_topic_id, '93: "Pre-test Odds" =:', '["Pre-test Probability / (1 - Pre-test Probability)", "Sensitivity / Specificity", "Prevalence x Incidence", "1 / LR"]', 0, 'Odds and probability are related but distinct mathematical concepts.'),
    (v_topic_id, '94: "Post-test Odds" =:', '["Pre-test Odds x Likelihood Ratio", "Pre-test Probability", "Sensitivity", "Specificity"]', 0, 'This is the Bayesian formula in odds form.'),
    (v_topic_id, '95: "Verification Bias" occurs when:', '["The test result is not verified", "The results of the test being studied influence whether the \"gold standard\" test is performed", "The lab makes a mistake", "The patient lies"]', 1, 'This typically happens if only those with a positive screening test get the invasive gold standard test.'),
    (v_topic_id, '96: "Spectrum Bias" occurs when a test is studied in:', '["A large group of people", "A population that doesn''t represent the typical spectrum of health and disease (e.g., only the very sick and the very healthy)", "A single hospital", "A laboratory"]', 1, 'This often makes the test look more accurate than it is in real practice.'),
    (v_topic_id, '97: "Reference Standard" (Gold Standard) is the:', '["Best available method for determining the presence or absence of disease", "Standard lab range", "The textbook", "The cheapest test"]', 0, 'All new diagnostic tests are compared against the reference standard.'),
    (v_topic_id, '98: "Evidence-Based History" involves knowing:', '["The patient''s name", "The Likelihood Ratios of specific symptoms and signs", "How to use a stethoscope", "Medical history"]', 1, 'Example: Knowing that a sudden "thunderclap" headache has a high LR for SAH.'),
    (v_topic_id, '99: "Diagnostic Uncertainty" is:', '["A sign of a bad doctor", "An inherent and manageable part of clinical practice", "Impossible with modern labs", "Always dangerous"]', 1, 'Acknowledge it and use a "test of time" or safety-netting.'),
    (v_topic_id, '100: "Shared Decision Making" is a process where:', '["The doctor decides", "The patient decides alone", "Clinicians and patients work together to make decisions based on clinical evidence and patient preferences", "Insurance decides"]', 2, 'Crucial for preference-sensitive decisions where there is no single "best" path.');
